// Simple per-IP rate limit for score posts
const lastPost = new Map();
setInterval(() => { const now = Date.now(); for (const [k, t] of lastPost) if (now - t > 60000) lastPost.delete(k); }, 60000).unref();

function send(res, code, body, type, extra) {
  res.writeHead(code, Object.assign({ 'Content-Type': type || 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }, extra || {}));
  res.end(typeof body === 'string' ? body : JSON.stringify(body));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  const p = url.pathname;

  if (p === '/health') return send(res, 200, { ok: true });

  if (p === '/api/scores' && req.method === 'GET') return send(res, 200, { scores: top(5) });

  if (p === '/api/scores' && req.method === 'POST') {
    const ip = (req.headers['x-forwarded-for'] || req.socket.remoteAddress || '').split(',')[0].trim();
    const now = Date.now();
    if (lastPost.has(ip) && now - lastPost.get(ip) < 3000) return send(res, 429, { error: '잠시 후 다시 시도해 주세요.' });
    let raw = '';
    req.on('data', c => { raw += c; if (raw.length > 2000) req.destroy(); });
    req.on('end', () => {
      let b;
      try { b = JSON.parse(raw); } catch (e) { return send(res, 400, { error: '잘못된 요청입니다.' }); }
      const name = String(b.name || '').replace(/[\u0000-\u001f<>"'`]/g, '').trim().slice(0, 10);
      const score = Math.floor(Number(b.score));
      const stage = Math.floor(Number(b.stage));
      if (!name) return send(res, 400, { error: '이름을 입력해 주세요.' });
      if (!Number.isFinite(score) || score < 0 || score > 20000000) return send(res, 400, { error: '점수가 올바르지 않습니다.' });
      if (!Number.isFinite(stage) || stage < 1 || stage > 31) return send(res, 400, { error: '스테이지가 올바르지 않습니다.' });
      lastPost.set(ip, now);
      scores.push({ name, score, stage, at: now });
      scores.sort((a, b2) => b2.score - a.score || a.at - b2.at);
      scores = scores.slice(0, KEEP);
      save();
      send(res, 200, { scores: top(5) });
    });
    return;
  }

  if ((p === '/' || p === '/index.html') && req.method === 'GET') return send(res, 200, PAGE, 'text/html; charset=utf-8', { 'Cache-Control': 'no-cache' });

  send(res, 404, { error: 'not found' });
});

server.listen(PORT, () => console.log(`STACK SIEGE running on :${PORT}`));
